import React from 'react';
import './ATSAnalyser.css';

export default function ATSAnalyser() {
  return (
    <div className="coming-soon-page">
      <div className="cs-icon">🔬</div>
      <h1 className="cs-title">ATS Analyser</h1>
      <p className="cs-text">This feature is currently under development.</p>
      <p className="cs-sub">Advanced AI-powered resume analysis will be available soon.</p>
      <div className="cs-badge">Coming Soon...</div>
    </div>
  );
}
